float4 frag(UPEInput i)
{
    float a = saturate(i.uv.x);   // iz yaşı: 0 baş (kılıç) → 1 kuyruk
    float v = saturate(i.uv.y);   // 0 kök → 1 uç
    // lifler iz boyunca uzanır: enine sık, boyuna uzun gürültü
    float fib = vnoise(float2(a * _Fiber * 0.08, v * _Fiber));
    float fib2 = vnoise(float2(a * _Fiber * 0.03 + 7.3, v * _Fiber * 0.35));
    // kökten uca kalınlık: kök kenarı tırtıklı fırça kenarı, kuyruğa doğru kök kenarı uca çekilir (iz incelir)
    float rootEdge = _RootCut + a * _TailThin + (fib2 - 0.5) * 0.12;
    float shp = AASTEP(rootEdge, v);
    // uç kenar: başta tam, kuyrukta hafif içeri
    float tipEdge = 1.0 - a * 0.08 - (vnoise(float2(a * _Fiber * 0.2, 3.1)) - 0.5) * 0.04;
    shp *= 1.0 - AASTEP(tipEdge, v);
    // kuru fırça erimesi: yaş arttıkça lif boşlukları açılır, kökten uca doğru
    float e = smoothstep(_ErodeStart, 1.0, a);
    float thr = e * (1.15 - 0.35 * v);
    shp *= AASTEP(thr, fib * 0.65 + fib2 * 0.35);
    // baş: kılıcın hemen arkası temiz ve dolu
    shp *= AASTEP(0.004, a);
    // renk bantları (enine): uçta mürekkep kenarı, altında açık çekirdek bandı, gövde
    float vn = (v - rootEdge) / max(tipEdge - rootEdge, 0.001);
    float ink = AASTEP(1.0 - _InkWidth * (1.0 + (fib2 - 0.5) * 0.8), vn);
    float rootInk = 1.0 - AASTEP(_InkWidth * 0.6 * (1.0 + (fib - 0.5)), vn);
    float coreW = _CoreBand * (1.0 - smoothstep(0.0, _CoreLen, a));
    float core = AASTEP(1.0 - _InkWidth - coreW, vn) * (1.0 - ink) * AASTEP(0.35, fib + 0.3 * (1.0 - a));
    float3 c = _BodyColor.rgb;
    // gövdede ikinci (gölge) bant: köke yakın koyu
    c = lerp(_ShadeColor.rgb, c, AASTEP(_ShadeBand, vn + (fib - 0.5) * 0.15));
    c = lerp(c, _CoreColor.rgb, core);
    c = lerp(c, _InkColor.rgb, max(ink, rootInk));
    c *= i.color.rgb;
    return float4(c, shp * i.color.a);
}
